// Read the order (webhook body) and build the two messages.
const o = $input.first().json.body ?? $input.first().json;

// Normalise the Indian mobile to WhatsApp format: 91 + 10 digits.
const digits = String(o.phone || '').replace(/\D/g, '').replace(/^0+/, '');
const customerPhone = digits.length === 10 ? '91' + digits : digits;

// >>> SET THE OWNER'S WHATSAPP NUMBER HERE (country code + number, no +) <<<
const ownerPhone = '91XXXXXXXXXX';

const i = o.items || {};
const rupees = (n) => 'Rs.' + Number(n || 0).toFixed(2);

const customerMessage =
  `Hi ${o.name}! Your SliceMatic order ${o.orderId ? '#' + o.orderId : ''} is confirmed.\n` +
  `${o.quantity} x ${i.pizza} on ${i.base} with ${i.topping}\n` +
  `Total: ${rupees(o.total)} (${o.payment_mode})\n` +
  `Arriving in ~30 min. Thank you for ordering!`;

const ownerMessage =
  `NEW ORDER ${o.orderId ? '#' + o.orderId : ''}\n` +
  `${o.quantity} pizza(s) - ${rupees(o.total)} (${o.payment_mode})\n` +
  `Item: ${i.base} / ${i.pizza} / ${i.topping}\n` +
  `Customer: ${o.name} (+${customerPhone})`;

return [{ json: { customerPhone, ownerPhone, customerMessage, ownerMessage } }];
